<?php

declare(strict_types=1);

$e = static fn (string $value): string => htmlspecialchars($value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
$filterAction = '/csi/reports';
$exportQuery = http_build_query(array_filter($summary['filters'], static fn (mixed $value): bool => $value !== null && $value !== ''));
$exportSuffix = $exportQuery === '' ? '' : '?' . $exportQuery;
$attended = 0;
$resolved = 0;
foreach ($summary['statuses'] as $status) {
    if (in_array($status['code'], ['in_progress', 'resolved', 'closed'], true)) { $attended += $status['total']; }
    if (in_array($status['code'], ['resolved', 'closed'], true)) { $resolved += $status['total']; }
}
?>
